// Flatten webhook body + normalize field types
const body = $('Webhook - Prior Auth Request1').first().json.body || {};
let dx = body.diagnosis_codes ?? body.diagnosis_code ?? [];
if (typeof dx === 'string') dx = dx.split(',');
dx = dx.map(c => String(c).trim().toUpperCase()).filter(Boolean);
const s = v => (v === undefined || v === null) ? '' : String(v).trim();
return [{ json: {
  patient_id: s(body.patient_id),
  encounter_id: s(body.encounter_id),
  procedure_code: s(body.procedure_code).toUpperCase(),
  diagnosis_codes: dx,
  physician_npi: s(body.physician_npi),
  payer_id: s(body.payer_id),
  payer_member_id: s(body.payer_member_id),
  clinical_note: s(body.clinical_note),
  mock_outcome: s(body.mock_outcome).toLowerCase(),
  // One ID for the whole run: emails, Supabase and Availity all use it.
  // Random suffix avoids collisions when many requests arrive in the same millisecond.
  requestId: 'AUTH-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6).toUpperCase()
}}];

// Merge FHIR data + decode clinical notes + validate codes
// Parse FHIR responses even if n8n returned them as text
const fhir = (name) => {
  let x = $(name).first().json || {};
  if (typeof x.data === 'string') { try { x = JSON.parse(x.data); } catch (e) {} }
  return x;
};
const webhookData = $('Code - Normalize Request1').first().json;
const patientRes = fhir('Epic FHIR - Get Patient1');
const encounterRes = fhir('Epic FHIR - Get Encounter1');
const notesRes = fhir('Epic FHIR - Get Clinical Notes1');
const coverageRes = fhir('Epic FHIR - Get Coverage1');

// Extract patient name from FHIR HumanName
let patientName = 'Unknown';
let firstName = '';
let lastName = '';
if (patientRes.name && patientRes.name[0]) {
  const given = (patientRes.name[0].given || []).join(' ');
  const family = patientRes.name[0].family || '';
  patientName = `${given} ${family}`.trim();
  firstName = (patientRes.name[0].given || [])[0] || '';
  lastName = family;
}

const patientDob = patientRes.birthDate || null;
const patientGender = patientRes.gender || null;

// Extract active coverage
let memberId = webhookData.payer_member_id || null;
let groupNumber = null;
let payerName = null;
if (coverageRes.entry && coverageRes.entry[0] && coverageRes.entry[0].resource) {
  const cov = coverageRes.entry[0].resource;
  memberId = cov.subscriberId || cov.identifier?.[0]?.value || memberId;
  groupNumber = cov.class?.[0]?.value || null;
  payerName = cov.payor?.[0]?.display || null;
}

// Decode clinical note (Base64)
let clinicalNote = '';
try {
  if (notesRes.entry && notesRes.entry[0]?.resource?.content?.[0]?.attachment?.data) {
    const b64 = notesRes.entry[0].resource.content[0].attachment.data;
    clinicalNote = Buffer.from(b64, 'base64').toString('utf-8');
  }
} catch (e) {
  clinicalNote = '[Unable to decode clinical note]';
}
// Fallback: use note sent in the request if Epic text is unavailable
let noteSource = clinicalNote ? 'epic' : null;
if (!clinicalNote && webhookData.clinical_note) { clinicalNote = webhookData.clinical_note; noteSource = 'request'; }
// Epic usually returns a Binary link instead of inline text (needs Binary.Read API)
const noteBinaryUrl = notesRes.entry?.[0]?.resource?.content?.[0]?.attachment?.url || null;
const noteCount = (notesRes.entry || []).filter(e => e.resource?.resourceType === 'DocumentReference').length;

// Generate unique requestId
const requestId = webhookData.requestId || ('AUTH-' + Date.now());

// Normalize diagnosis codes (support both diagnosis_code and diagnosis_codes)
let diagnosisCodes = webhookData.diagnosis_codes || [];
if (typeof diagnosisCodes === 'string') {
  diagnosisCodes = [diagnosisCodes];
}

// Validate ICD-10 format
const icd10Regex = /^[A-Z][0-9]{2}(\.[A-Z0-9]{1,4})?$/;
const invalidIcd = diagnosisCodes.filter(c => !icd10Regex.test(c));

// Validate CPT format
const cptRegex = /^[0-9]{4}[0-9A-Z]$|^[0-9]{4}F$/;
const procedureCode = webhookData.procedure_code;
const isValidCpt = cptRegex.test(procedureCode);

return [{
  json: {
    requestId,
    mock_outcome: webhookData.mock_outcome || '',
    patient_id: webhookData.patient_id,
    encounter_id: webhookData.encounter_id,
    procedure_code: procedureCode,
    diagnosis_codes: diagnosisCodes,
    physician_npi: webhookData.physician_npi,
    payer_id: webhookData.payer_id,
    patient: {
      name: patientName,
      firstName,
      lastName,
      dateOfBirth: patientDob,
      gender: patientGender,
      memberId,
      groupNumber
    },
    payerName,
    clinicalNote,
    encounter: encounterRes.resourceType === 'Encounter' ? { id: encounterRes.id, status: encounterRes.status, type: encounterRes.type?.[0]?.text || null, period: encounterRes.period || null } : null,
    validation: {
      invalidIcdCodes: invalidIcd,
      isValidCpt,
      hasClinicalNote: clinicalNote.length > 0,
      noteSource,
      noteCount,
      noteBinaryUrl,
      encounterFound: encounterRes.resourceType === 'Encounter'
    }
  }
}];

// Parse AI (OpenAI) response safely with fallbacks
const mergeData = $('Code - Merge FHIR + Decode Notes1').first().json;
const claudeRes = $input.first().json;

let clinical = {
  primary_diagnosis: mergeData.diagnosis_codes[0] || 'Unknown',
  secondary_diagnoses: mergeData.diagnosis_codes.slice(1) || [],
  procedure_requested: 'Procedure ' + mergeData.procedure_code,
  procedure_cpt_code: mergeData.procedure_code,
  clinical_justification: 'Clinical justification could not be generated automatically. Manual review required.',
  supporting_evidence: [],
  alternative_treatments_tried: [],
  urgency_level: 'routine',
  estimated_duration_days: 30,
  medical_necessity_statement: 'Medical necessity determination pending clinical review.'
};

try {
  let text = '';
  if (claudeRes.choices && claudeRes.choices[0]?.message?.content) {
    text = claudeRes.choices[0].message.content; // OpenAI
  } else if (claudeRes.content && claudeRes.content[0] && claudeRes.content[0].text) {
    text = claudeRes.content[0].text; // Claude
  } else if (typeof claudeRes === 'string') {
    text = claudeRes;
  }

  // Strip markdown fences
  text = text.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(text);

  clinical = {
    primary_diagnosis: parsed.primary_diagnosis || clinical.primary_diagnosis,
    secondary_diagnoses: parsed.secondary_diagnoses || clinical.secondary_diagnoses,
    procedure_requested: parsed.procedure_requested || clinical.procedure_requested,
    procedure_cpt_code: parsed.procedure_cpt_code || clinical.procedure_cpt_code,
    clinical_justification: parsed.clinical_justification || clinical.clinical_justification,
    supporting_evidence: parsed.supporting_evidence || [],
    alternative_treatments_tried: parsed.alternative_treatments_tried || [],
    urgency_level: ['routine', 'urgent', 'emergent'].includes(parsed.urgency_level)
      ? parsed.urgency_level
      : 'routine',
    estimated_duration_days: typeof parsed.estimated_duration_days === 'number'
      ? parsed.estimated_duration_days
      : 30,
    medical_necessity_statement: parsed.medical_necessity_statement || clinical.medical_necessity_statement,
    documentation_gaps: parsed.documentation_gaps || [],
    insufficient_documentation: parsed.insufficient_documentation === true
  };
} catch (e) {
  // Keep fallback values — never halt workflow on AI parsing errors
}

// Never auto-submit without a real clinical note or when AI flags gaps
const noNote = !mergeData.validation?.hasClinicalNote;
const reviewRequired =
  clinical.urgency_level === 'emergent' ||
  clinical.estimated_duration_days < 3 ||
  noNote ||
  clinical.insufficient_documentation === true;

return [{
  json: {
    ...mergeData,
    clinical,
    auditTrail: {
      reviewRequired,
      reviewReason: noNote ? 'No clinical note retrieved from EHR' : (clinical.insufficient_documentation ? 'AI flagged insufficient documentation' : (clinical.urgency_level === 'emergent' ? 'Emergent case' : (clinical.estimated_duration_days < 3 ? 'Short duration' : null))),
      extractedAt: new Date().toISOString(),
      aiError: claudeRes.error ? (claudeRes.error.message || JSON.stringify(claudeRes.error)) : null
    }
  }
}];

// Evaluate Availity coverage response (handles In Process polling)
const res = $input.first().json || {};
const cov = (res.coverages && res.coverages[0]) || res;
const statusCode = String(cov.statusCode ?? '');
const plans = cov.plans || [];
const ACTIVE = ['1','2','3','4','5'];          // X12 EB01 active codes
const activePlan = plans.find(p => ACTIVE.includes(String(p.statusCode)));
const polls = $runIndex;                        // how many times we've looped
let eligibility, message;
if (res.error || res.errors || res.userMessage) {
  eligibility = 'error';
  message = res.error || res.userMessage || JSON.stringify(res.errors);
} else if (statusCode === '0') {
  eligibility = polls >= 5 ? 'error' : 'in_process';
  message = polls >= 5 ? 'Payer did not respond after 5 checks' : 'Payer still processing';
} else if (statusCode === '4') {
  eligibility = activePlan ? 'active' : 'inactive';
  message = activePlan ? activePlan.status : (plans[0]?.status || 'No active plan returned');
} else {
  eligibility = 'error';
  message = cov.status || ('Unexpected status code ' + statusCode);
}
return [{ json: {
  eligibility, message,
  coverageId: cov.id || null,
  coverageStatus: cov.status || null,
  planStatus: activePlan?.status || plans[0]?.status || null,
  payerName: cov.payer?.name || null,
  validationMessages: cov.validationMessages || [],
  polls
}}];

// Build the service review (prior auth) request
const c = $('Code - Parse Claude Response').first().json;
const cfg = $('Config1').first().json;
const urgencyMap = { routine: 'R', urgent: 'U', emergent: 'E' };
const request = {
  payerId: c.payer_id,
  requestingProvider: { npi: c.physician_npi, organizationNpi: cfg.ORG_NPI },
  patient: { memberId: c.patient.memberId, firstName: c.patient.firstName, lastName: c.patient.lastName, birthDate: c.patient.dateOfBirth },
  serviceRequest: {
    procedureCodes: [c.procedure_code],
    diagnosisCodes: c.diagnosis_codes,
    urgencyCode: urgencyMap[c.clinical.urgency_level] || 'R'
  },
  clinicalInfo: {
    medicalNecessityStatement: c.clinical.medical_necessity_statement,
    clinicalNotes: c.clinical.clinical_justification
  }
};
const mode = (cfg.AVAILITY_PA_MODE || 'mock').toLowerCase();
const mockOutcome = (c.mock_outcome || cfg.MOCK_PA_OUTCOME || 'approved').toLowerCase();
return [{ json: { mode, mockOutcome, request } }];

// Simulated Availity service-review responses for testing
const outcome = $json.mockOutcome;
const now = Date.now();
const responses = {
  approved: { status: 'approved', statusCode: 'A1', authorizationNumber: 'MOCK-A' + String(now).slice(-6), certificationEffectiveDate: $now.toFormat('yyyy-MM-dd'), certificationExpirationDate: $now.plus({ days: 90 }).toFormat('yyyy-MM-dd') },
  denied:   { status: 'denied', statusCode: 'A3', denialReasonCode: 'NMN', denialReason: 'Not medically necessary - insufficient evidence of failed conservative therapy' },
  pending:  { status: 'pending', statusCode: 'A4', trackingId: 'MOCK-TRK-' + String(now).slice(-6), message: 'Pended for medical review' },
  error:    { error: 'Mock payer timeout' }
};
return [{ json: { ...(responses[outcome] || responses.approved), mock: true } }];

// Normalize payer response -> approved | denied | pending | error
const r = $input.first().json || {};
const raw = String(r.status || r.authorizationStatus || r.certificationStatus || r.statusCode || '').toLowerCase();
let paStatus = 'error';
if (['approved','a1','certified'].includes(raw)) paStatus = 'approved';
else if (['denied','a3','not_certified','rejected'].includes(raw)) paStatus = 'denied';
else if (['pending','a4','p','pended','in process','0'].includes(raw)) paStatus = 'pending';
return [{ json: {
  paStatus,
  authNumber: r.authorizationNumber || r.authNumber || null,
  trackingId: r.trackingId || r.id || null,
  denialReason: r.denialReason || r.reason || null,
  denialCode: r.denialReasonCode || r.reasonCode || null,
  effectiveDate: r.certificationEffectiveDate || null,
  expirationDate: r.certificationExpirationDate || null,
  mock: r.mock === true,
  rawError: paStatus === 'error' ? (r.error || r.userMessage || JSON.stringify(r).slice(0, 500)) : null
}}];
